    ai_model: Optional[OcsfAiModel] = Field(default=None, title="AI Model", description="""The AI model involved in this operation. Use for direct model invocations where no autonomous agent is involved. For agent-mediated operations, model identity is carried within <code>ai_agent.ai_model</code> instead.""")
    delegation: Optional[OcsfDelegation] = Field(default=None, title="Delegation", description="""The delegation under whose authority this AI operation was performed. Links the event to a durable authorization context independent of traces and sessions, enabling correlation of all events executed under the same delegated authority.""")
    message_context: Optional[OcsfMessageContext] = Field(default=None, title="Message Context", description="""Communication context for AI system interactions including protocols, roles, clients, and session information for MCP and other AI communication systems.""")


