    impact: Optional[str] = Field(default=None, title="Impact", description="""The impact , normalized to the caption of the impact_id value. In the case of 'Other', it is defined by the event source.""")
    impact_id: Optional[int] = Field(default=None, title="Impact ID", description="""The normalized impact of the incident or finding. Per NIST, this is the magnitude of harm that can be expected to result from the consequences of unauthorized disclosure, modification, destruction, or loss of information or information system availability.""")
    impact_score: Optional[int] = Field(default=None, title="Impact Score", description="""The impact as an integer value of the finding, valid range 0-100.""")
    is_suspected_breach: Optional[Bool] = Field(default=None, title="Suspected Breach", description="""A determination based on analytics as to whether a potential breach was found.""")
    priority: Optional[str] = Field(default=None, title="Priority", description="""The priority, normalized to the caption of the priority_id value. In the case of 'Other', it is defined by the event source.""")
    priority_id: Optional[int] = Field(default=None, title="Priority ID", description="""The normalized priority. Priority identifies the relative importance of the incident or finding. It is a measurement of urgency.""")
