    ticket: Optional[OcsfTicket] = Field(default=None, title="Ticket", description="""The linked ticket in the ticketing system.""")
    tickets: Optional[list[OcsfTicket]] = Field(default=None, title="Tickets", description="""The associated ticket(s) in the ticketing system. Each ticket contains details like ticket ID, status, etc.""")
    verdict: Optional[str] = Field(default=None, title="Verdict", description="""The verdict assigned to an Incident finding.""")
