    is_backed_up: Optional[Bool] = Field(default=None, title="Back Ups Configured", description="""Indicates whether the device or resource has a backup enabled, such as an automated snapshot or a cloud backup. For example, this is indicated by the <code>cloudBackupEnabled</code> value within JAMF Pro mobile devices or the registration of an AWS ARN with the AWS Backup service.""")
    is_encrypted: Optional[Bool] = Field(default=None, title="Encrypted", description="""Indicates if the databucket is encrypted.""")
    is_public: Optional[Bool] = Field(default=None, title="Public", description="""Indicates if the databucket is publicly accessible.""")
    modified_time_dt: Optional[str] = Field(default=None, title="Modified Time", description="""The most recent time when any changes, updates, or modifications were made within the databucket.""")
