    type_id: int = Field(default=..., title="Type ID", description="""The normalized identifier of the databucket type.""")
    version: Optional[str] = Field(default=None, title="Version", description="""The version of the resource. For example <code>1.2.3</code>.""")
    zone: Optional[str] = Field(default=None, title="Cloud Availability Zone", description="""The specific availability zone within a cloud region where the databucket is located.""")
