    avg_timespan: Optional[OcsfTimespan] = Field(default=None, title="Average Timespan", description="""The average time to patch.""")
    bulletin: Optional[str] = Field(default=None, title="Patch Bulletin", description="""The kb article bulletin identifier.""")
    classification: Optional[str] = Field(default=None, title="Classification", description="""The vendors classification of the kb article.""")
    created_time: Optional[int] = Field(default=None, title="Created Time", description="""The date the kb article was released by the vendor.""")
    created_time_dt: Optional[str] = Field(default=None, title="Created Time", description="""The date the kb article was released by the vendor.""")
    install_state: Optional[str] = Field(default=None, title="Install State", description="""The install state of the kb article.""")
    install_state_id: Optional[int] = Field(default=None, title="Install State ID", description="""The normalized install state ID of the kb article.""")
    is_superseded: Optional[Bool] = Field(default=None, title="The patch is superseded.", description="""The kb article has been replaced by another.""")
    os: Optional[OcsfOs] = Field(default=None, title="OS", description="""The operating system the kb article applies.""")
    product: Optional[OcsfProduct] = Field(default=None, title="Product", description="""The product details the kb article applies.""")
    severity: Optional[str] = Field(default=None, title="Severity", description="""The severity of the kb article.""")
    size: Optional[int] = Field(default=None, title="Size", description="""The size in bytes for the kb article.""")
    src_url: Optional[str] = Field(default=None, title="Source URL", description="""The kb article link from the source vendor.""")
    title: Optional[str] = Field(default=None, title="Title", description="""The title of the kb article.""")
