    start_time: Optional[int] = Field(default=None, title="Start Time", description="""The timestamp indicating when the scan job began execution.""")
    start_time_dt: Optional[str] = Field(default=None, title="Start Time", description="""The timestamp indicating when the scan job began execution.""")
    unique_malware_count: Optional[int] = Field(default=None, title="Unique Malware Count", description="""The number of unique malware detected across all infected files.""")
    type: Optional[str] = Field(default=None, title="Type", description="""The type of scan.""")
    type_id: int = Field(default=..., title="Type ID", description="""The type id of the scan.""")
