    ip: Optional[str] = Field(default=None, title="IP Address", description="""The IP address associated with the network interface.""")
    mac: Optional[str] = Field(default=None, title="MAC Address", description="""The MAC address of the network interface.""")
    namespace: Optional[str] = Field(default=None, title="Namespace", description="""The namespace is useful in merger or acquisition situations. For example, when similar entities exist that you need to keep separate.""")
    open_ports: Optional[list[OcsfPortInfo]] = Field(default=None, title="Open Ports", description="""The list of open ports on a network interface, including port numbers and associated protocol information.""")
    subnet_prefix: Optional[int] = Field(default=None, title="Subnet Prefix Length", description="""The subnet prefix length determines the number of bits used to represent the network part of the IP address. The remaining bits are reserved for identifying individual hosts within that subnet.""")
    type: Optional[str] = Field(default=None, title="Type", description="""The type of network interface.""")
    type_id: Optional[int] = Field(default=None, title="Type ID", description="""The network interface type identifier.""")
    name: Optional[str] = Field(default=None, title="Name", description="""The name of the network interface.""")
    uid: Optional[str] = Field(default=None, title="Unique ID", description="""The unique identifier for the network interface.""")
    uid_numeric: Optional[int] = Field(default=None, title="Numeric Unique ID", description="""The <code>uid</code> attribute in numeric form where applicable.<br><strong>Note:</strong> Producers may populate <code>uid_numeric</code> only in addition to <code>uid</code> and not as an alternative to it.""")


