    license: Optional[str] = Field(default=None, title="Software License", description="""The software license applied to this component.""")
    name: str = Field(default=..., title="Name", description="""The software component name.""")
    purl: Optional[str] = Field(default=None, title="Package URL", description="""The Package URL (PURL) to identify the software component. This is a URL that uniquely identifies the component, including the component's name, version, and type. The URL is used to locate and retrieve the component's metadata and content.""")
    related_component: Optional[str] = Field(default=None, title="Related Component", description="""The package URL (PURL) of the component that this software component has a relationship with.""")
    relationship: Optional[str] = Field(default=None, title="Relationship", description="""The relationship between two software components, normalized to the caption of the <code>relationship_id</code> value. In the case of 'Other', it is defined by the source.""")
    relationship_id: Optional[int] = Field(default=None, title="Relationship ID", description="""The normalized identifier of the relationship between two software components.""")
    type: Optional[str] = Field(default=None, title="Type", description="""The type of software component, normalized to the caption of the <code>type_id</code> value. In the case of 'Other', it is defined by the source.""")
