    type: Optional[str] = Field(default=None, title="Type", description="""The type of the UAS. For example, Helicopter, Gyroplane, Rocket, etc.""")
    type_id: Optional[int] = Field(default=None, title="Type ID", description="""The UAS type identifier.""")
    uuid: Optional[str] = Field(default=None, title="UTM UUID", description="""The Unmanned Aircraft System Traffic Management (UTM) provided universal unique ID (UUID) traceable to a non-obfuscated ID where this UTM UUID acts as a 'session id' to protect exposure of operationally sensitive information.""")
    location: Optional[OcsfLocation] = Field(default=None, title="UAS Position Location Information", description="""The detailed geographical location usually associated with an IP address.""")
    model: Optional[str] = Field(default=None, title="Model", description="""The model name of the aircraft or unmanned system.""")
    serial_number: Optional[str] = Field(default=None, title="Serial Number", description="""The serial number of the unmanned system. This is expressed in <code>CTA-2063-A</code> format.""")
    speed: Optional[str] = Field(default=None, title="Speed", description="""Ground speed of flight. This value is provided in meters per second with a minimum resolution of 0.25 m/s. Special Values: <code>Invalid</code>, <code>No Value</code>, or <code>Unknown: 255 m/s</code>.""")
    speed_accuracy: Optional[str] = Field(default=None, title="Speed Accuracy", description="""Provides quality/containment on horizontal ground speed. Measured in meters/second.""")
    track_direction: Optional[str] = Field(default=None, title="Track Direction", description="""Direction of flight expressed as a “True North-based” ground track angle. This value is provided in clockwise degrees with a minimum resolution of 1 degree. If aircraft is not moving horizontally, use the “Unknown” value""")
    uid_alt: Optional[str] = Field(default=None, title="UAS Alternate ID", description="""A secondary identification identifier for an unmanned system. This can be a Serial Number (in <code>CTA-2063-A</code> format, the Registration ID (provided by the <code>CAA</code>, a UTM, or a unique Session ID.""")
    vertical_speed: Optional[str] = Field(default=None, title="Vertical Speed", description="""Vertical speed upward relative to the WGS-84 datum, measured in meters per second. Special Values: <code>Invalid</code>, <code>No Value</code>, or <code>Unknown: 63 m/s</code>.""")
    name: Optional[str] = Field(default=None, title="Name", description="""The name of the unmanned system as reported by tracking or sensing hardware.""")
    uid: Optional[str] = Field(default=None, title="UAS ID", description="""The primary identification identifier for an unmanned system. This can be a Serial Number (in <code>CTA-2063-A</code> format, the Registration ID (provided by the <code>CAA</code>, a UTM, or a unique Session ID.""")
    uid_numeric: Optional[int] = Field(default=None, title="Numeric Unique ID", description="""The <code>uid</code> attribute in numeric form where applicable.<br><strong>Note:</strong> Producers may populate <code>uid_numeric</code> only in addition to <code>uid</code> and not as an alternative to it.""")


