    actor: OcsfActor = Field(default=..., title="Actor", description="""The user, process, or service that initiated the activity on the host. For system-level events this is typically a process; for IAM events it is typically a user or role.""")
    device: Optional[OcsfDevice] = Field(default=None, title="Device", description="""The host or device where the activity was observed. Populate with details such as hostname, IP address, OS, and hardware identifiers when available from the source.""")
