    attestation_list: Optional[list[OcsfAttestation]] = Field(default=None, title="Attestation List", description="""One or more cryptographic <code>attestation</code> objects over an event, each providing integrity, authenticity, and non-repudiation. Independent attesters over the same event — for example a producer at write time and a downstream processor at ingest — each contribute a separate attestation, distinct from co-signers on a single attestation, which share its <code>signatures</code> array. Carried on the <code>record_integrity</code> profile; the object itself is domain-agnostic.""")
    action: Optional[str] = Field(default=None, title="Action", description="""The normalized caption of <code>action_id</code>.""")
    action_id: Optional[int] = Field(default=None, title="Action ID", description="""The action taken by a control or other policy-based system leading to an outcome or disposition. An unknown action may still correspond to a known disposition. Refer to <code>disposition_id</code> for the outcome of the action.""")
    attacks: Optional[list[OcsfAttack]] = Field(default=None, title="MITRE ATT&CK® and ATLAS™ Details", description="""An array of MITRE ATT&CK® objects describing identified tactics, techniques & sub-techniques. The objects are compatible with MITRE ATLAS™ tactics, techniques & sub-techniques.""")
    authorizations: Optional[list[OcsfAuthorization]] = Field(default=None, title="Authorization Information", description="""Provides details about an authorization, such as authorization outcome, and any associated policies related to the activity/event.""")
    confidence: Optional[str] = Field(default=None, title="Confidence", description="""The confidence, normalized to the caption of the confidence_id value. In the case of 'Other', it is defined by the event source.""")
    confidence_id: Optional[int] = Field(default=None, title="Confidence ID", description="""The normalized confidence refers to the accuracy of the security control or alert. An analytic with a low confidence means that the alerts may be noisy or may not be malicious in nature.""")
    confidence_score: Optional[int] = Field(default=None, title="Confidence Score", description="""The confidence score as reported by the event source. If <code>confidence_id</code> is 99 'Other', it should be the same as <code>confidence</code> if both are populated.""")
    disposition: Optional[str] = Field(default=None, title="Disposition", description="""The disposition name, normalized to the caption of the disposition_id value. In the case of 'Other', it is defined by the event source.""")
    disposition_id: Optional[int] = Field(default=None, title="Disposition ID", description="""Describes the outcome or action taken by a security control, such as access control checks, malware detections or various types of policy violations.""")
    firewall_rule: Optional[OcsfFirewallRule] = Field(default=None, title="Firewall Rule", description="""The firewall rule that pertains to the control that triggered the event, if applicable.""")
    is_alert: Optional[Bool] = Field(default=None, title="Alert", description="""Indicates that the event is considered to be an alertable signal. Should be set to <code>true</code> if <code>disposition_id = Alert</code> among other dispositions, and/or <code>risk_level_id</code> or <code>severity_id</code> of the event is elevated. Not all control events will be alertable, for example if <code>disposition_id = Exonerated</code> or <code>disposition_id = Allowed</code>.""")
    malware: Optional[list[OcsfMalware]] = Field(default=None, title="Malware", description="""A list of Malware objects, describing details about the identified malware.""")
    malware_scan_info: Optional[OcsfMalwareScanInfo] = Field(default=None, title="Malware Scan Info", description="""Describes details about the scan job that identified malware on the target system.""")
    policy: Optional[OcsfPolicy] = Field(default=None, title="Policy", description="""The policy that pertains to the control that triggered the event, if applicable. For example the name of an anti-malware policy or an access control policy.""")
    risk_details: Optional[str] = Field(default=None, title="Risk Details", description="""Describes the risk associated with the finding.""")
    risk_level: Optional[str] = Field(default=None, title="Risk Level", description="""The risk level, normalized to the caption of the risk_level_id value.""")
    risk_level_id: Optional[int] = Field(default=None, title="Risk Level ID", description="""The normalized risk level id.""")
    risk_score: Optional[int] = Field(default=None, title="Risk Score", description="""The risk score as reported by the event source.""")


