    activity_name: Optional[str] = Field(default=None, title="Activity", description="""The event activity name, as defined by the <code>activity_id</code>. When <code>activity_id</code> is <code>99</code> (Other), this attribute <b>must</b> contain the source-specific activity label. For all other <code>activity_id</code> values, this must match the caption defined for that <code>activity_id</code> enum value.""")
    category_name: Optional[str] = Field(default=None, title="Category", description="""The event category name, as defined by category_uid value: <code>Discovery</code>.""")
    category_uid: int = Field(default=..., title="Category ID", description="""The category unique identifier of the event. Each event class belongs to exactly one category. Producers and mappers must set this to the category defined by the event class being used."""    , le=5, ge=5)
