    activity_id: int = Field(default=..., title="Activity ID", description="""The normalized identifier of the Data Security Finding activity.""")
    activity_name: Optional[str] = Field(default=None, title="Activity", description="""The Data Security finding activity name, as defined by the <code>activity_id</code>.""")
