    ai_agent: Optional[OcsfAiAgent] = Field(default=None, title="AI Agent", description="""The autonomous AI agent that performed this operation. Carries model identity via <code>ai_agent.ai_model</code>. Populate when the action was performed by an agent rather than a direct model call.""")
