    tls: Optional[OcsfTls] = Field(default=None, title="TLS", description="""The Transport Layer Security (TLS) attributes.""")
    traffic: Optional[OcsfNetworkTraffic] = Field(default=None, title="Traffic", description="""The network traffic refers to the amount of data moving across a network at a given point of time. Intended to be used alongside Network Connection.""")
